with open("region.fasta") as f:
    lines = f.read().split("\n")
header = lines[0]
seq = "".join(l.strip() for l in lines[1:] if l.strip())
print(header, len(seq))
comp = {"A":"T","T":"A","G":"C","C":"G","N":"N"}
rc = "".join(comp[c] for c in reversed(seq))

codon_table = {
 'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L',
 'ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V',
 'TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
 'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
 'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
 'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
 'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
 'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}

def translate(s):
    return "".join(codon_table.get(s[i:i+3],"X") for i in range(0,len(s)-2,3))

def orfs(s, minlen=100):
    res=[]
    for strand,seq2 in [("+",s),("-",rc)]:
        for frame in range(3):
            t = translate(seq2[frame:])
            aa = t.split("*")
            pos=0
            for pep in aa:
                start = pos*3
                if len(pep)>=minlen:
                    # coordinates in original seq
                    if strand=="+":
                        s0=frame+start; e0=frame+start+len(pep)*3
                    else:
                        e0=len(s)-frame-start; s0=len(s)-frame-start-len(pep)*3
                    res.append((strand,frame,len(pep),s0,e0))
                pos += len(pep)+1
    return res

for o in sorted(orfs(seq,50), key=lambda x:-x[2])[:20]:
    print(o)
